from pathlib import Path
import re,json,hashlib,html
R=Path(__file__).resolve().parents[2];P=R/'public';A=json.loads((R/'scripts/project-sources/collapse-press-assets.json').read_text());esc=html.escape
css='''.cp-press-features .cp-press-image{display:block;position:relative;aspect-ratio:485/686;overflow:hidden;background:#f5f3ef;border:0;padding:0;margin:0;min-height:0}.cp-press-image img{display:block;width:100%;height:100%;object-fit:cover;object-position:center}.cp-press-features .cp-press-image--client img{width:200%;max-width:none;height:100%;object-fit:fill}.cp-press-publication{display:flex;justify-content:space-between;gap:14px;padding:16px 0;border-bottom:1px solid #69655f;font:11px/1.5 "IBM Plex Mono",monospace;text-transform:uppercase}.cp-press-publication strong{font-weight:400}.cp-press-features article{scroll-margin-top:80px}.cp-archive-search{max-width:680px;margin:30px 0 20px}.cp-archive-search label{display:block;font:11px/1.5 "IBM Plex Mono",monospace;text-transform:uppercase;margin-bottom:9px}.cp-archive-search input{display:block;width:100%;min-height:48px;padding:12px 14px;background:transparent;color:#121210;border:1px solid #8b857d;border-radius:0;font:17px/1.4 "Inter Tight",Arial,sans-serif}.cp-archive-search input:focus-visible{outline:2px solid #a6532a;outline-offset:4px}.cp-archive-status{font:11px/1.6 "IBM Plex Mono",monospace;margin:0 0 24px;text-transform:uppercase}.cp-archive-item[hidden],.cp-more[hidden],[data-archive-empty][hidden]{display:none!important}.cp-pack-documentation{padding-top:22px}.cp-pack-documentation figure{margin:0}.cp-pack-documentation img{width:100%;height:auto;display:block}.cp-pack-documentation figcaption,.cp-pack-documentation p{font:12px/1.6 "IBM Plex Mono",monospace;margin:14px 0}.cp-pack-documentation a{font:11px/1.5 "IBM Plex Mono",monospace;display:inline-block;border-bottom:1px solid;padding:10px 0}.cp-archive-details[open]{grid-column:span 2}.cp-archive-grid{align-items:start}.cp-archive-item{height:100%}.cp-archive-details[open]{height:auto}.cp-filter-toolbar button{min-height:44px}.cp-filter-toolbar{gap:10px}.cp-filter-toolbar button .cp-filter-count{margin-left:8px;opacity:.6}.cp-archive-empty{font-size:18px}@media(max-width:650px){.cp-press-features{grid-template-columns:1fr}.cp-press-image{max-height:none}.cp-press-publication{font-size:10px}.cp-archive-search{max-width:none}.cp-filter-toolbar{gap:8px}.cp-filter-toolbar button{padding:11px;font-size:10px}.cp-archive-details[open]{grid-column:1/-1}}
'''
css+='.cp-press-image--nasty img{position:absolute;top:-15.1%;left:-2.4%;width:104.8%;max-width:none;height:auto;object-fit:initial}'
style='collapse-press-'+hashlib.sha256(css.encode()).hexdigest()[:12]+'.css';(P/'assets'/style).write_text(css)
js='''(()=>{const root=document.querySelector('.cp-archive');if(!root)return;const cards=[...root.querySelectorAll('.cp-archive-item')],filters=[...root.querySelectorAll('[data-filter]')],input=root.querySelector('[data-archive-query]'),status=root.querySelector('[data-archive-status]'),empty=root.querySelector('[data-archive-empty]'),toggle=root.querySelector('.cp-more');const it=document.documentElement.lang==='it';let category='all',expanded=true;const normal=s=>s.normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();function render(){const query=normal(input.value.trim());const matching=cards.filter(c=>(category==='all'||c.dataset.category===category)&&normal(c.textContent).includes(query));for(const c of cards){const index=matching.indexOf(c);c.hidden=index<0||(!expanded&&!query&&index>=8);}for(const b of filters){const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}const shown=matching.filter(c=>!c.hidden).length;status.textContent=it?shown+' di '+matching.length+' voci / '+cards.length+' in archivio':shown+' of '+matching.length+' entries / '+cards.length+' in the archive';empty.hidden=matching.length>0;toggle.hidden=!!query||matching.length<=8;toggle.textContent=(expanded?toggle.dataset.expanded:toggle.dataset.collapsed)+(expanded?' ↑':' ↓');toggle.setAttribute('aria-expanded',String(expanded));}for(const b of filters)b.addEventListener('click',()=>{category=b.dataset.filter;expanded=true;render();});input.addEventListener('input',render);input.addEventListener('keydown',event=>{if(event.key==='Escape'){input.value='';render();}});toggle.addEventListener('click',()=>{expanded=!expanded;render();});render();})();'''
script='collapse-archive-'+hashlib.sha256(js.encode()).hexdigest()[:12]+'.js';(P/'assets'/script).write_text(js)
def image(k,alt):
 v=A[k][-1];return '<img src="'+v['src']+'" srcset="'+', '.join(x['src']+' '+str(x['width'])+'w' for x in A[k])+'" sizes="(max-width:650px) calc(100vw - 28px), calc(50vw - 30px)" width="'+str(v['width'])+'" height="'+str(v['height'])+'" loading="lazy" decoding="async" alt="'+esc(alt)+'">'
for it in [False,True]:
 T=lambda a,b:a if it else b;pre='it/' if it else '';p=P/(pre+'work/collapse/index.html');s=p.read_text()
 s=s.replace('</head>',f'<link rel="stylesheet" href="/assets/{style}"></head>');s=re.sub(r'<script src="/assets/(?:static/)?collapse-archive-[^"]+" defer></script>',f'<script src="/assets/{script}" defer></script>',s)
 # Keep publication credits and links; replace typographic placeholders with original editorial images.
 for k,name,issue,title,url,alt in [('nasty','NASTY MAGAZINE','01 / EDITORIAL','ESSERE A CASA','https://www.nastymagazine.com/fashion/essere-a-casa-by-lorenzo-nafissi/',T('COLLAPSE nell’editoriale Essere a casa — foto Lorenzo Nafissi','COLLAPSE in the Essere a casa editorial — photography Lorenzo Nafissi')),('client','CLIENT MAGAZINE','02 / ISSUE #24','DI CHI TI RICORDI PER SORRIDERE','https://www.clientmagazine.co.uk/di-chi-ti-ricordi-per-sorridere-by-michele-vitale-for-client-magazine-24/',T('Capi COLLAPSE in CLIENT #24 — foto Michele Vitale','COLLAPSE pieces in CLIENT #24 — photography Michele Vitale'))]:
  poster=r'<article><div class="cp-poster cp-poster-'+('dark' if k=='nasty' else 'light')+r'">.*?</div>'
  replacement='<article id="press-'+k+'"><a class="cp-press-image'+(' cp-press-image--client' if k=='client' else ' cp-press-image--nasty')+'" href="'+url+'" target="_blank" rel="noopener noreferrer" aria-label="'+T('Apri l’editoriale su ','Open the editorial on ')+name+'">'+image(k,alt)+'</a><div class="cp-press-publication"><strong>'+name+'</strong><span>'+issue+'</span></div>'
  s,n=re.subn(poster,lambda m:replacement,s,count=1,flags=re.S);assert n==1
 # Replace the real packaging entry with original photography and factual documentation.
 pattern=r'<details class="cp-archive-item cp-archive-details" data-category="design"><summary><span class="cp-card-meta">016 / DESIGN</span>.*?</details>'
 pack='<details class="cp-archive-item cp-archive-details" data-category="design" id="archive-pack"><summary><span class="cp-card-meta">016 / DESIGN</span><span class="cp-card-main"><span>PACKAGING</span><strong class="cp-card-title">COLLAPSE PACK</strong><span class="cp-card-description">'+T('Scatola del brand e impiego di cartone recuperato.','Brand packaging and the use of recovered cardboard.')+'</span></span><span class="cp-open" aria-hidden="true">+</span></summary><div class="cp-pack-documentation"><figure>'+image('pack',T('Scatola COLLAPSE — documentazione originale del brand','COLLAPSE box — original brand documentation'))+'<figcaption>COLLAPSE PACK / '+T('FOTO DALL’ARCHIVIO DEL BRAND','PHOTO FROM THE BRAND ARCHIVE')+'</figcaption></figure><p>'+T('Il progetto usa cartone di recupero proveniente da aziende locali, come descritto dal brand. Il marchio rimane l’elemento grafico centrale della scatola.','The project uses recovered cardboard from local businesses, as described by the brand. The mark remains the central graphic element on the box.')+'</p><a href="https://collapsestore.com/pages/sustainability" target="_blank" rel="noopener noreferrer">'+T('LEGGI IL PROGETTO SUL SITO COLLAPSE','READ THE PROJECT ON THE COLLAPSE WEBSITE')+' ↗</a></div></details>'
 s,n=re.subn(pattern,lambda m:pack,s,count=1,flags=re.S);assert n==1
 # Real search and category counts. Native HTML still exposes every entry without JavaScript.
 search='<div class="cp-archive-search"><label for="collapse-archive-query">'+T('Cerca nell’archivio','Search the archive')+'</label><input id="collapse-archive-query" data-archive-query type="search" autocomplete="off" placeholder="'+T('Nome, collaborazione o progetto','Name, collaboration or project')+'" aria-controls="collapse-archive-grid"></div>'
 s=s.replace('<div class="cp-filter-toolbar"',search+'<div class="cp-filter-toolbar"',1)
 toolbar=re.search(r'<div class="cp-filter-toolbar".*?</div>',s,re.S)[0]
 for category,count in [('all',18),('press',7),('events',8),('design',3)]:
  toolbar=re.sub(r'(<button[^>]*data-filter="'+category+r'"[^>]*>)(.*?)(</button>)',lambda m:m[1]+m[2]+'<span class="cp-filter-count" aria-hidden="true">'+str(count)+'</span>'+m[3],toolbar)
 s=re.sub(r'<div class="cp-filter-toolbar".*?</div>',lambda m:toolbar+'<p class="cp-archive-status" data-archive-status role="status" aria-live="polite">18 / '+T('VOCI IN ARCHIVIO','ARCHIVE ENTRIES')+'</p>',s,count=1,flags=re.S)
 s=s.replace('<div class="cp-archive-grid">','<div class="cp-archive-grid" id="collapse-archive-grid">',1).replace('<button type="button" class="cp-more"','<p class="cp-archive-empty" data-archive-empty hidden>'+T('Nessuna voce corrisponde alla ricerca.','No entries match this search.')+'</p><button type="button" class="cp-more" aria-controls="collapse-archive-grid"',1)
 # Match chapter order rather than misleading legacy numbers.
 for old,new in [('17 / CO-FOUNDER','01 / CO-FOUNDER'),('04 / FASHION','02 / FASHION'),('33 / SOCIAL','03 / SOCIAL'),('35 / DIGITAL PRODUCT','04 / DIGITAL PRODUCT'),('71 / FASHION EDITORIAL','05 / FASHION EDITORIAL'),('41 / SELECTED EXPERIENCES','06 / SELECTED EXPERIENCES')]:s=s.replace(old,new)
 for old,new in [('17','01'),('04','02'),('33','03'),('35','04'),('71','05'),('41','06')]:s=s.replace('<span class="cp-nav-number">'+old+'</span>','<span class="cp-nav-number">'+new+'</span>')
 s=s.replace('THE COMPLETE<br>ARCHIVE.','SELECTED<br>EXPERIENCES.')
 s=s.replace('Every project, collaboration and event in one searchable archive. Each arrow links to the original source or project.','Collaborations, publications and events: the work of COLLAPSE beyond its collections. Search by name or explore each area.')
 s=s.replace('Tutti i progetti, le collaborazioni e gli eventi in una griglia consultabile. Ogni freccia apre il post o il progetto originale.','Collaborazioni, pubblicazioni ed eventi: il lavoro di COLLAPSE oltre le collezioni. Cerca per nome o esplora ogni ambito.')
 p.write_text(s)
print(style,script)
